#!/usr/bin/env bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# hdd_trace.sh (kit v10): one hdd_run.sh call with a block-I/O trace and a height sampler beside it, for G016's
# diagnosis stage (arms W and V). The timing stages (arms F and N) do not use it. For the HDD VM.
#
# In order:
#   1. finds the disk under $DATA_DIR, its device number as the block tracepoint reports it, and the partition's first
#      sector (sysfs); logs them;
#   2. starts bpftrace on bioread_vm.bt as root (sudo), its PID written to <trace dir>/bpf.pid by a one-line shell that
#      then execs bpftrace; waits 20 s for it to attach and aborts (exit 5, before hdd_run.sh starts) if it has exited
#      by then (anything it printed to stderr meanwhile is logged);
#   3. runs hdd_run.sh (unchanged) in the background; takes the node's PID from hdd_run.sh's own "monerod pid" line
#      and starts sampler_vm.py on it (height every 5 s, CLOCK_MONOTONIC);
#   4. when hdd_run.sh exits: stops the sampler, stops bpftrace with SIGINT (SIGKILL after 30 s), writes the FIEMAP
#      extents of the run's data.mdb (filefrag -v) to fiemap.txt, and prints hdd_run.sh's output, one TRACE line and
#      HDD_TRACE_DONE <trace dir>. It exits with hdd_run.sh's exit code.
# The trace dir gets: run.log (with "test node pid <pid>, mono0 <ns>" and "partstart <sectors>"), bio.txt, bio.err,
# samples.csv, fiemap.txt, run.out; and, if the driver set MONERODATO_G016_WLOG, the LMDB page-event log.
# Sizes per 7,000-block run on this VM, estimated: bio.txt 40-60 MB (every write bio is a line), the event log about
# 100 MB, the rest under 1 MB.
# It touches nothing outside the trace dir, $OUT_BASE (through hdd_run.sh) and $DATA_DIR (through hdd_run.sh).
#
# usage: hdd_trace.sh <trace dir> <label> <monerod binary>
# environment: as hdd_run.sh (SNAP_MDB, DATA_DIR, PEER, OUT_BASE, RPC_PORT, ...), plus
#   RUN       path of hdd_run.sh (required)
#   BT        the bpftrace script (default: bioread_vm.bt next to this script)
#   SAMPLER   the sampler (default: sampler_vm.py next to this script)
#   BPFTRACE  the bpftrace binary (default bpftrace); FILEFRAG (default filefrag)
set -u
TR=${1:?usage: hdd_trace.sh <trace dir> <label> <monerod binary>}; LABEL=${2:?label}; BIN=${3:?monerod binary}
: "${RUN:?}" "${DATA_DIR:?}" "${OUT_BASE:?}"
here=$(dirname "$(realpath "$0")")
BT=${BT:-$here/bioread_vm.bt}; SAMPLER=${SAMPLER:-$here/sampler_vm.py}; BPFTRACE=${BPFTRACE:-bpftrace}; FILEFRAG=${FILEFRAG:-filefrag}
RPC_PORT=${RPC_PORT:-28091}
mkdir -p "$TR" || exit 5
lg() { echo "$*" | tee -a "$TR/run.log"; }
lg "trace start $(date -u +%FT%TZ); label $LABEL; bt $BT ($(sha256sum "$BT" | cut -c1-16)); sampler $SAMPLER ($(sha256sum "$SAMPLER" | cut -c1-16))"
# 1. the disk
src=$(df --output=source "$DATA_DIR" | tail -1); part=$(basename "$(realpath "$src")")
if [ -e "/sys/class/block/$part/partition" ]; then
  disk=$(basename "$(dirname "$(realpath "/sys/class/block/$part")")"); pstart=$(cat "/sys/class/block/$part/start")
else
  disk=$part; pstart=0
fi
mm=$(cat "/sys/class/block/$disk/dev" 2> /dev/null) || { lg "TRACE_ABORT no sysfs dev for $disk"; exit 5; }
devt=$(( (${mm%%:*} << 20) | ${mm##*:} ))
lg "data dir $DATA_DIR on $src; disk $disk ($mm, tracepoint dev $devt); partstart $pstart"
# 2. the tracer
mono0=$(python3 -I -c 'import time; print(time.monotonic_ns())')
sudo -n sh -c 'echo $$ > "$1"; exec "$2" -q "$3" "$4"' sh "$TR/bpf.pid" "$BPFTRACE" "$BT" "$devt" > "$TR/bio.txt" 2> "$TR/bio.err" &
bp=""
for i in $(seq 1 20); do
  sleep 1; [ -z "$bp" ] && bp=$(cat "$TR/bpf.pid" 2> /dev/null)
  if [ -n "$bp" ] && [ ! -d "/proc/$bp" ]; then
    lg "TRACE_ABORT bpftrace exited: $(head -c 300 "$TR/bio.err")"; exit 5
  fi
done
[ -n "$bp" ] && [ -d "/proc/$bp" ] || { lg "TRACE_ABORT bpftrace pid unknown or gone: $(head -c 300 "$TR/bio.err")"; exit 5; }
[ -s "$TR/bio.err" ] && lg "bpftrace stderr (it runs on): $(head -c 300 "$TR/bio.err")"
lg "bpftrace pid $bp; running 20 s; bio.txt $(wc -l < "$TR/bio.txt") lines so far"
# 3. the run
touch "$TR/start.stamp"
bash "$RUN" "$LABEL" "$BIN" > "$TR/run.out" 2>&1 &
rp=$!
pid=""; sp=""
while [ -z "$pid" ] && kill -0 "$rp" 2> /dev/null; do
  d=$(find "$OUT_BASE" -maxdepth 1 -type d -name "*-$LABEL" -newer "$TR/start.stamp" 2> /dev/null | sort | tail -1)
  [ -n "$d" ] && pid=$(grep -oE '^monerod pid [0-9]+' "$d/summary.txt" 2> /dev/null | grep -oE '[0-9]+$')
  [ -z "$pid" ] && sleep 1
done
if [ -n "$pid" ]; then
  lg "test node pid $pid, mono0 $mono0, partstart $pstart"
  python3 -I "$SAMPLER" "$RPC_PORT" "$pid" "$TR/samples.csv" 2> "$TR/sampler.err" &
  sp=$!
else
  lg "no monerod pid seen (hdd_run.sh ended first)"
fi
wait "$rp"; rc=$?
# 4. stop, and the extents
[ -n "$sp" ] && kill "$sp" 2> /dev/null
sudo -n kill -INT "$bp" 2> /dev/null
for i in $(seq 1 30); do [ -d "/proc/$bp" ] || break; sleep 1; done
[ -d "/proc/$bp" ] && { sudo -n kill -KILL "$bp" 2> /dev/null; lg "bpftrace killed after 30 s"; }
"$FILEFRAG" -v "$DATA_DIR/testnet/lmdb/data.mdb" > "$TR/fiemap.txt" 2>&1 || lg "filefrag failed"
cat "$TR/run.out"
bio=$(wc -l < "$TR/bio.txt"); reads=0
[ -n "$pid" ] && reads=$(awk -v p="$pid" '$2 == p && $4 ~ /R/' "$TR/bio.txt" | wc -l)
smp=$(( $(wc -l < "$TR/samples.csv" 2> /dev/null || echo 1) - 1 )); [ "$smp" -lt 0 ] && smp=0
ext=$(grep -cE '^ *[0-9]+: ' "$TR/fiemap.txt")
wl="na"; WLF=${MONERODATO_G016_WLOG:-}
[ -n "$WLF" ] && [ -f "$WLF" ] && wl=$(awk '{c[$1]++} END {printf "W:%d,F:%d,D:%d,C:%d", c["W"], c["F"], c["D"], c["C"]}' "$WLF")
lg "TRACE label=$LABEL pid=${pid:-na} bio_lines=$bio node_reads=$reads samples=$smp fiemap_extents=$ext partstart=$pstart wlog=$wl rc=$rc dir=$TR"
echo "HDD_TRACE_DONE $TR"
exit $rc
